#!/usr/bin/env node
/*
 * Generates supabase/seed_tests.sql — one INSERT per test, containing that
 * test's title/question_count/duration and its full questions array as jsonb.
 *
 * Run once after applying supabase/schema.sql, by pasting the generated file's
 * contents into the Supabase SQL Editor. Re-run and re-paste any time
 * scripts/question-bank.js changes.
 *
 *   node scripts/export-supabase-seed.js
 */
'use strict';

const fs = require('fs');
const path = require('path');
const { getSectionsForTest } = require('./lib/build-sections.js');

const TOTAL_TESTS = 20;
const DURATION_MINUTES = 150;
const OUT_FILE = path.join(__dirname, '..', 'supabase', 'seed_tests.sql');

function sqlLiteral(value) {
  // Dollar-quoted string: safe even if the text contains single quotes
  // (several questions use possessives like "Piaget's theory").
  return `$jsonq$${value}$jsonq$`;
}

const lines = [];
lines.push('-- Auto-generated by scripts/export-supabase-seed.js — do not edit by hand.');
lines.push('-- Run this once (after supabase/schema.sql) in the Supabase SQL Editor.');
lines.push('-- Re-run scripts/export-supabase-seed.js and re-paste if the question bank changes.');
lines.push('');
lines.push('insert into test_content (test_id, title, question_count, duration_minutes, questions)');
lines.push('values');

const rows = [];
for (let testId = 1; testId <= TOTAL_TESTS; testId++) {
  const sections = getSectionsForTest(testId);
  const questionCount = sections.reduce((sum, s) => sum + s.questions.length, 0);
  const idPadded = String(testId).padStart(2, '0');
  const title = `TET Full Test ${idPadded}`;
  const questionsJson = JSON.stringify(sections);
  rows.push(
    `  ('test${idPadded}', ${sqlLiteral(title)}, ${questionCount}, ${DURATION_MINUTES}, ${sqlLiteral(questionsJson)}::jsonb)`
  );
}
lines.push(rows.join(',\n'));
lines.push('on conflict (test_id) do update set');
lines.push('  title = excluded.title,');
lines.push('  question_count = excluded.question_count,');
lines.push('  duration_minutes = excluded.duration_minutes,');
lines.push('  questions = excluded.questions;');
lines.push('');

fs.writeFileSync(OUT_FILE, lines.join('\n'));
console.log(`Wrote ${OUT_FILE} (${TOTAL_TESTS} tests).`);
